export function isRegexPatternValid(pattern: string) {
  let isValid = true;
  try {
    new RegExp(pattern);
  } catch (e) {
    isValid = false;
  }

  return isValid;
}

export function removeNonNumeric(inputString: any) {
  // Use regular expression to match only numbers (0-9)
  const numbersOnly = inputString.replace(/[^\d]/g, '');
  return numbersOnly as string;
}

export function validateAmount(value: any, allowNegative = false) {
  let isValid = true;
  try {
    let allowedCharsRegex = /^[0-9,.]+$/;

    if (allowNegative) {
      allowedCharsRegex = /^-?[0-9,.]+$/;
    }

    if (!allowedCharsRegex.test(value)) {
      isValid = false;

      return;
    }
  } catch (e) {
    isValid = false;
  }

  return isValid;
}
